package com.pulsepay.event;
import com.fasterxml.jackson.databind.JsonNode; import com.fasterxml.jackson.databind.ObjectMapper; import java.util.UUID; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.kafka.annotation.KafkaListener; import org.springframework.stereotype.Component; import org.springframework.transaction.annotation.Transactional;
@Component public class PaymentEventConsumer { private final JdbcTemplate db; private final ObjectMapper json; public PaymentEventConsumer(JdbcTemplate db,ObjectMapper json){this.db=db;this.json=json;} @KafkaListener(topics="payment.events",groupId="pulsepay-webhook-dispatch") @Transactional public void consume(String payload)throws Exception{JsonNode event=json.readTree(payload);UUID eventId=UUID.fromString(event.path("event_id").asText());UUID merchantId=UUID.fromString(event.path("merchant_id").asText());String type=event.path("event_type").asText();if(type.isBlank())throw new IllegalArgumentException("event_type is required");if(db.update("insert into processed_events(event_id)values(?) on conflict do nothing",eventId)==0)return;db.update("insert into webhook_events(id,merchant_id,event_type,payload)values(?,?,?,cast(? as jsonb))",eventId,merchantId,type,payload);var endpoints=db.query("select id from webhook_endpoints where merchant_id=? and enabled=true and jsonb_exists(event_types, ?)",(rs,i)->UUID.fromString(rs.getString(1)),merchantId,type);for(UUID endpoint:endpoints)db.update("insert into webhook_deliveries(webhook_endpoint_id,event_id,event_type,payload)values(?,?,?,cast(? as jsonb)) on conflict do nothing",endpoint,eventId,type,payload);} }
